CREATE TABLE IF NOT EXISTS Members (
principalId TEXT,
roleDefinitionId TEXT,
roleName TEXT
);

INSERT INTO Members (principalId, roleDefinitionId, roleName)
SELECT
MT.principalId,
MT.roleDefinitionId,
DR.displayName AS roleName
FROM MembersTemp MT
LEFT JOIN DirectoryRoles DR ON DR.id = MT.roleDefinitionId;

select principalId from Members;
